feed:
    {{ config.title | escape_xml | safe }}
    {%- if term is defined and term %} - {{ term.name | escape_xml | safe }}
    {%- elif section is defined and section.title %} - {{ section.title | escape_xml | safe }}
	{%- else %} - All Posts
    {%- endif -%}


		{%- if section is defined and section.description %}
		{{ section.description | escape_xml | safe }}
	{%- else %}
		{{ config.description | escape_xml | safe }}
	{%- endif %}


	{%- if section is defined and section -%}
		{{ section.permalink | escape_xml | safe }}
	{%- else -%}
		{{ config.base_url | escape_xml | safe }}
	{%- endif -%}

    {%- if not feed_url is defined %}
        {%- set feed_url = page.permalink | trim_end(pat="/") %}
    {%- endif %}



        {{ config.extra.author.name | escape_xml | safe }}
        {{ config.base_url | escape_xml | safe }}
        {{ config.extra.author.email | escape_xml | safe }}

    Zola
    {{ last_updated | default(value=now()) | date(format="%Y-%m-%dT%H:%M:%S%:z") }}

	{%- for p in pages %}
		{%- set category = "" -%}
		{%- set cat_url = "" -%}

		{%- if p.taxonomies.categories -%}
			{%- set category = p.taxonomies.categories[0] -%}
			{%- set cat_url = get_url(path='@/posts/'~category~'/_index.md') -%}
			{%- set section = get_section(path='posts/'~category~'/_index.md') %}
			{%- if section.extra.singular %}{%- set category = section.extra.singular -%}{% endif %}
		{%- endif %}
	{%- if p.relative_path is starting_with(pat="posts/") %}

		{{ p.permalink | escape_xml | safe }}


			{%- if p.title -%}
				{{ p.title | escape_xml | safe }}
			{%- else -%}
				{%- if category -%}{{ category }}{% else %}Post{%- endif %} from {{ p.date | date(format="%Y-%m-%d at %H:%M") }}
			{%- endif -%}

        {{ p.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
        {{ p.updated | default(value=p.date, boolean=true) | date(format="%Y-%m-%dT%H:%M:%S%:z") }}

		{#- Grab the first, and usually only, category #}
		{%- if p.taxonomies.categories %}

		{%- endif %}

		{#- Some posts have descriptions, which we can use as summaries #}
		{%- if p.description %}
		{{ p.description | escape_xml | safe }}
		{%- endif %}

		{#- Not all post types have content #}
		{%- if p.content %}
		{{- p.content }}

		{%- endif %}

		{#- Bookmarks get an extra tag for the bookmark URL #}
		{%- if p.extra["bookmark-of"] %}

		{%- endif %}

	{%- endif %}
	{%- endfor %}
